      port: 3080,
      networkingMode: "mirrored",
      browserHint: "http://127.0.0.1:3081/",
      advice: ["tip"],
    });
    assert.match(text, /browserHint: http:\/\/127\.0\.0\.1:3081\//);
    assert.match(text, /tip/);
  });
